INSERT INTO score_components (id, score_id, code, name, description) VALUES ('786136d0-6470-58c9-a485-8a123515127e', '25619fb1-0e18-52f6-9a4e-e7c6471e05bd', 'economic_throughput', 'Economic throughput', 'Trailing user-paid fee revenue, annualized. Fees are the hardest evidence of willingness to pay for blockspace.');
