INSERT INTO projects (id, slug, name, symbol, coingecko_id, defillama_slug, thesis_category_id, launch_date, launch_notes, status) VALUES ('9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', 'sol', 'Solana', 'SOL', 'solana', 'Solana', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', '2020-03-16', 'Mainnet beta launch.', 'active');
INSERT INTO projects (id, slug, name, symbol, coingecko_id, defillama_slug, thesis_category_id, launch_date, launch_notes, status) VALUES ('2cb6fd6a-1754-5e88-b408-3805d17281d2', 'xrp', 'XRP', 'XRP', 'ripple', NULL, '79a43c1f-d952-579c-90c5-8c4a346a13a1', '2012-06-01', 'XRP Ledger originates 2012 (first ledger closes June 2012); created by Ripple Labs founders.', 'active');
INSERT INTO projects (id, slug, name, symbol, coingecko_id, defillama_slug, thesis_category_id, launch_date, launch_notes, status) VALUES ('182d6ffa-b26c-56a6-aa8a-a08b691d8d73', 'link', 'Chainlink', 'LINK', 'chainlink', NULL, 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', '2017-06-01', 'Whitepaper published June 2017; token sale September 2017; oracle mainnet May 2019.', 'active');
INSERT INTO projects (id, slug, name, symbol, coingecko_id, defillama_slug, thesis_category_id, launch_date, launch_notes, status) VALUES ('fa865acf-744a-509b-b53a-193a50e40d48', 'ada', 'Cardano', 'ADA', 'cardano', 'Cardano', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', '2017-09-29', 'Mainnet launch September 2017.', 'active');
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('6bf5bd7e-f47b-58f3-90f1-b5b0696d846f', 'a9b173a8-b996-5a1b-aa94-e8f987299124', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become a globally held, politically neutral monetary asset — digital gold — that preserves purchasing power over long horizons and settles finality without trusted intermediaries.', 'Sustained demand as a long-duration store of value across cycles: growing holder base, deep liquid markets, institutional/sovereign allocation, and fee-paying settlement demand independent of speculation.', NULL);
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('c49877d7-6766-588f-a1d7-39b359e9fb27', '15de9695-1aa6-54a2-80b9-79029c6f79b3', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become the dominant programmable settlement and execution layer for decentralized applications and tokenized value — the base layer others build financial infrastructure on.', 'Majority share of onchain economic activity (fees, DEX volume, stablecoin settlement); enterprises and institutions building on or settling via Ethereum; sustained developer dominance.', NULL);
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('de102545-4c66-5968-9707-1b26c08293f1', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become the high-throughput execution layer for consumer-scale crypto applications — fast, cheap settlement for onchain trading, payments, and DePIN.', 'Sustained high-retention consumer application usage (trading, payments, DePIN) with activity persisting independent of token incentives.', NULL);
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('58a633ca-35d0-5c3c-ad44-50104dd65606', '2cb6fd6a-1754-5e88-b408-3805d17281d2', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become the bridge asset and settlement rail for cross-border institutional payments — the currency banks use to move value between corridors.', 'Banks and payment providers using XRP itself (not just Ripple messaging software) for settlement at meaningful, recurring volume.', NULL);
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('53ef1b9e-10cf-50da-a674-73a4263fb611', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become the standard decentralized oracle infrastructure that smart contracts depend on for market data and offchain computation.', 'Dominant share of oracle-secured value across chains, with node operators earning sustainable fee revenue from data consumers and major enterprise integrations.', NULL);
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('88eeaa13-42c7-5e66-9953-7a0bbe070a61', 'fa865acf-744a-509b-b53a-193a50e40d48', 'd77ca462-57cb-529b-9c75-1db17367525d', 'Become a peer-reviewed, formally-verified smart contract platform for global financial and identity infrastructure — the academically rigorous alternative.', 'Meaningful developer and user adoption of Cardano smart contracts, with real-world identity or financial deployments operating at scale.', NULL);
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('bbe52eb1-ccb3-589e-96dc-d0f56d604648', 'a9b173a8-b996-5a1b-aa94-e8f987299124', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 10, 'The token IS the monetary asset. There is no Bitcoin protocol without BTC; security, settlement, and the store-of-value thesis are all denominated in it.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('0a5d42ba-e4c5-5d21-82e3-e6e1164c9ba5', 'a9b173a8-b996-5a1b-aa94-e8f987299124', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 6.5, 'No cash flows, no burn, no staking. Capture is purely monetary premium on a credibly fixed 21M supply — works only if the SoV thesis holds.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('d42f71d5-c782-56da-86ea-2cea0efe21ab', 'a9b173a8-b996-5a1b-aa94-e8f987299124', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 9, 'A successful neutral global monetary asset would be among the most consequential financial developments in a century. Highest-impact category in the taxonomy.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('117056d1-46db-5564-9692-a15e67b2e473', '15de9695-1aa6-54a2-80b9-79029c6f79b3', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 9, 'ETH is required to pay gas for all execution and to stake for network security. The protocol cannot function without a native fee/staking asset; only the ticker could theoretically change.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('00d8973a-367c-5b60-b23f-9c108931c765', '15de9695-1aa6-54a2-80b9-79029c6f79b3', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 7.5, 'EIP-1559 fee burn plus staking yield give direct value linkage, but L2s siphon execution and fee revenue is far below the 2021 peak. Capture is real but diluted versus the thesis.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('0ecadd4e-efac-503e-9b7e-5cc00119a66a', '15de9695-1aa6-54a2-80b9-79029c6f79b3', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 9, 'The dominant programmable settlement layer for tokenized global finance would be foundational infrastructure — comparable to the early internet''s TCP/IP layer.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('5291f4ce-f561-5686-88cb-c557e98f2abc', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 9, 'SOL pays all transaction fees and secures the network via staking. No SOL, no Solana.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('51546d69-a10c-51c2-937b-13087e1462ff', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 6.5, 'Fees are intentionally tiny (a design goal), so capture leans on staking yield funded partly by issuance — dilutive. MEV adds some. Weaker direct linkage than ETH''s burn.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('dcc96c8a-4d40-5567-87c3-9b0a4829023b', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 7.5, 'A successful consumer-scale execution layer would be major financial infrastructure, but the thesis is narrower than Ethereum''s base-layer ambition.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('ea9cb4c2-1c38-5a5f-85b9-70936387c0c4', '2cb6fd6a-1754-5e88-b408-3805d17281d2', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 6, 'XRP is the ledger''s native bridge asset and spam deterrent, but Ripple''s payment products have historically worked with minimal XRP usage; institutions can and do settle without it.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('7352d188-59a2-598a-a9af-df16179f43a1', '2cb6fd6a-1754-5e88-b408-3805d17281d2', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 4, 'Negligible fee burn, no staking, large escrow overhang (tens of billions XRP released programmatically). Capture is almost entirely speculative premium.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('64f1f8b3-c815-5f5d-b5ea-253f126e6cc1', '2cb6fd6a-1754-5e88-b408-3805d17281d2', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 7, 'Capturing a share of global cross-border settlement would be highly consequential, but the thesis is narrower than a monetary asset or general execution layer.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('ff954b70-6181-51e4-a25b-799b44fe6986', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 8, 'Node operator payments, collateral, and staking are LINK-denominated by protocol design. A different token is conceivable but the cryptoeconomics are built around LINK.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('3d0b5b98-cfb2-58a0-ad45-ff53521f0004', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 5.5, 'Staking and explicit fee payments exist (Economics 2.0, BUILD/SCALE), but realized fee revenue remains small relative to FDV; most historical node payment was subsidized.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('6a9ee911-f5bb-5942-b3aa-d3b47bd694b7', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 6.5, 'Critical middleware for tokenized finance, but middleware: the largest value accrues to the applications and assets above it, not the oracle layer.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('d3903fa2-dfd2-59f6-8d4c-09b9e0947a9b', 'fa865acf-744a-509b-b53a-193a50e40d48', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_necessity', 9, 'ADA pays fees and secures the network via proof-of-stake delegation. No ADA, no Cardano.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('4191c4ab-4c70-5b0e-bcab-6654b0f8c3be', 'fa865acf-744a-509b-b53a-193a50e40d48', 'd77ca462-57cb-529b-9c75-1db17367525d', 'token_value_capture', 5.5, 'Staking yield exists but is funded substantially by reserves/issuance; user-paid fee demand is small, so the fee-driven linkage is weak.', NULL, '2026-09-19');
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('433c5fb6-3df6-5cdf-954a-1a7f338ba593', 'fa865acf-744a-509b-b53a-193a50e40d48', 'd77ca462-57cb-529b-9c75-1db17367525d', 'world_impact_potential', 7.5, 'Same category as Ethereum/Solana (execution layer), so the ceiling is comparable — assessed slightly below ETH given later start and narrower differentiation.', NULL, '2026-09-19');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('1789c28c-78db-5548-9908-18821b7784b5', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 0, 'Functional network exists', 'Mainnet producing blocks and accepting contract deployments. Block explorer or client release notes.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('1e179776-76cc-58ca-bff2-d030df4dfa6c', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 1, 'Independent developers and users', 'Third-party developers deploying contracts; non-team user transactions visible onchain. DApp listings, explorer activity.');
